//! Decides whether a copy must not be saved.

use std::sync::LazyLock;

use regex::Regex;

use crate::settings::Privacy;

/// Markers defined at http://nspasteboard.org and used by password managers.
pub const CONCEALED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
];

static SECRET_PATTERNS: LazyLock<Vec<Regex>> = LazyLock::new(|| {
    [
        r"-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----",
        r"\bAKIA[0-9A-Z]{16}\b",
        r"\bgh[pousr]_[A-Za-z0-9]{36,}\b",
        r"\bgithub_pat_[A-Za-z0-9_]{40,}\b",
        r"\bxox[abprs]-[A-Za-z0-9-]{10,}",
        r"\bsk-ant-[A-Za-z0-9_-]{20,}",
        r"\bsk-(?:proj-)?[A-Za-z0-9_-]{32,}",
        r"\bAIza[0-9A-Za-z_-]{35}\b",
        r"\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}",
    ]
    .iter()
    .map(|p| Regex::new(p).unwrap())
    .collect()
});

static CARD_RE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^[0-9][0-9 -]{11,22}[0-9]$").unwrap());

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum IgnoreReason {
    Concealed(String),
    ExcludedApp(String),
    Secret,
    Pattern(String),
}

pub struct PrivacyFilter {
    settings: Privacy,
    patterns: Vec<Regex>,
}

impl PrivacyFilter {
    pub fn new(settings: &Privacy) -> PrivacyFilter {
        let patterns = settings
            .ignore_patterns
            .iter()
            .filter_map(|p| match Regex::new(p) {
                Ok(re) => Some(re),
                Err(e) => {
                    tracing::warn!("ignoring invalid privacy pattern {p:?}: {e}");
                    None
                }
            })
            .collect();
        PrivacyFilter { settings: settings.clone(), patterns }
    }

    /// Checked before reading any data, so concealed content is never loaded.
    pub fn check_types(&self, types: &[String], source_app: Option<&str>) -> Option<IgnoreReason> {
        if self.settings.ignore_concealed
            && let Some(t) = types.iter().find(|t| CONCEALED_TYPES.contains(&t.as_str()))
        {
            return Some(IgnoreReason::Concealed(t.clone()));
        }
        let app = source_app?;
        self.settings
            .excluded_apps
            .iter()
            .any(|a| a.eq_ignore_ascii_case(app))
            .then(|| IgnoreReason::ExcludedApp(app.to_string()))
    }

    pub fn check_text(&self, text: &str) -> Option<IgnoreReason> {
        if self.settings.ignore_secrets && looks_secret(text) {
            return Some(IgnoreReason::Secret);
        }
        self.patterns.iter().find(|re| re.is_match(text)).map(|re| IgnoreReason::Pattern(re.as_str().to_string()))
    }
}

pub fn looks_secret(text: &str) -> bool {
    if text.len() > 100_000 {
        return false;
    }
    if SECRET_PATTERNS.iter().any(|re| re.is_match(text)) {
        return true;
    }
    let t = text.trim();
    CARD_RE.is_match(t) && luhn(t)
}

fn luhn(s: &str) -> bool {
    let digits: Vec<u32> = s.chars().filter_map(|c| c.to_digit(10)).collect();
    if !(13..=19).contains(&digits.len()) {
        return false;
    }
    let sum: u32 = digits
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| {
            if i % 2 == 1 {
                let d = d * 2;
                if d > 9 { d - 9 } else { d }
            } else {
                d
            }
        })
        .sum();
    sum.is_multiple_of(10)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn concealed_and_excluded() {
        let f = PrivacyFilter::new(&Privacy::default());
        let types = vec!["public.utf8-plain-text".to_string(), "org.nspasteboard.ConcealedType".to_string()];
        assert!(matches!(f.check_types(&types, None), Some(IgnoreReason::Concealed(_))));
        let plain = vec!["public.utf8-plain-text".to_string()];
        assert_eq!(f.check_types(&plain, Some("com.apple.Safari")), None);
        assert!(matches!(f.check_types(&plain, Some("com.1password.1password")), Some(IgnoreReason::ExcludedApp(_))));
    }

    #[test]
    fn secrets() {
        assert!(looks_secret("AKIAIOSFODNN7EXAMPLE"));
        assert!(looks_secret("token: ghp_abcdefghijklmnopqrstuvwxyz0123456789"));
        assert!(looks_secret("-----BEGIN OPENSSH PRIVATE KEY-----\nabc"));
        assert!(looks_secret("4111 1111 1111 1111"));
        assert!(!looks_secret("4111 1111 1111 1112"));
        assert!(!looks_secret("hello world"));
        assert!(!looks_secret("call me at 555 123 4567"));
    }

    #[test]
    fn custom_patterns() {
        let p = Privacy { ignore_patterns: vec!["(?i)internal only".into(), "([".into()], ..Privacy::default() };
        let f = PrivacyFilter::new(&p);
        assert!(f.check_text("this is INTERNAL ONLY").is_some());
        assert!(f.check_text("public").is_none());
    }
}
